discrete CommandParsingSystem
port:
    event input real ReceiveNewCommandRequest;
    event output real CommandExecution;
    event output real ErrorReporting;
state:
    initial state IDLE
        when entry() then
            statehold(0);
        end;
        when receive(ReceiveNewCommandRequest) then
            transition(RECEIVING_CMD);
        end;
    end;

    state RECEIVING_CMD
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(CMD_PROCESSING);
        end;
    end;

    state CMD_PROCESSING
        when entry() then
            statehold(0);
        end;
        when condition(ValidAndSupportedCommand) then
            transition(EXECUTING);
        end;
        when condition(InvalidOrUnsupportedCommand) then
            transition(IDLE);
        end;
    end;

    state EXECUTING
        when entry() then
            statehold(0);
        end;
        when condition(CommandExecutionFinished) then
            transition(IDLE);
            out
                send(CommandExecution, 1);
        end;
        when condition(CommandExecutionError) then
            transition(IDLE);
            out
                send(ErrorReporting, 1);
        end;
    end;
end;
end;

discrete DataTransferSystem
port:
    event input real PreparationComplete;
    event output real DataIntegrityCheck;
state:
    initial state READY_FOR_DATA
        when entry() then
            statehold(0);
        end;
        when receive(PreparationComplete) then
            transition(DATA_TRANSFER);
        end;
    end;

    state DATA_TRANSFER
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(CHECKSUM_VERIFICATION);
        end;
    end;

    state CHECKSUM_VERIFICATION
        when entry() then
            statehold(0);
        end;
        when condition(ChecksumMatches) then
            transition(READY_FOR_DATA);
        end;
        when condition(ChecksumMismatch) then
            transition(READY_FOR_DATA);
            out
                send(DataIntegrityCheck, 1);
        end;
    end;
end;
end;

discrete ErrorDetectionCorrectionSystem
port:
    event input real DataIntegrityCheck;
    event output real ErrorReporting;
state:
    initial state MONITORING
        when entry() then
            statehold(0);
        end;
        when receive(DataIntegrityCheck) then
            transition(ERROR_DETECTED);
        end;
    end;

    state ERROR_DETECTED
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(CORRECTION_ATTEMPTED);
        end;
    end;

    state CORRECTION_ATTEMPTED
        when entry() then
            statehold(0);
        end;
        when condition(CorrectionSuccessful) then
            transition(MONITORING);
        end;
        when condition(CorrectionFailed) then
            transition(ERROR_REPORTED);
            out
                send(ErrorReporting, 1);
        end;
    end;

    state ERROR_REPORTED
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(MONITORING);
        end;
    end;
end;
end;

